//! Original short survival event. No CAS ShipDef, combat table or account growth
//! is read or mutated by these deliberately separate arcade rules.
use crate::{model::{E,P,Entry},world::roll};
use serde::{Serialize,Deserialize};use serde_json::{json,Value};
pub const VERSION:&str="cas-event-tide-v1";
const DURATION:u32=180;
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]
pub struct Config{pub character_id:String,pub difficulty:String,pub intel_profile:String}
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]
pub struct Saved{pub version:String,pub seed:u32,pub config:Config,pub tick:u32,pub commands:Vec<Entry>}
#[derive(Clone,Debug)]struct Foe{id:u32,kind:&'static str,p:P,h:f64,hp:f64,max:f64,speed:f64,damage:f64,next:u32,warning:Option<(P,u32)>,elite:bool,boss:bool,hurt:u32}
#[derive(Clone,Debug,Serialize)]struct Drop{id:u32,x:f64,y:f64,value:u32}
#[derive(Clone,Debug)]struct Bolt{id:u32,p:P,h:f64,speed:f64,damage:f64,radius:f64,life:u32,kind:&'static str}
const UPGRADES:[(&str,&str,&str);9]=[("damage","过载炮膛","舰炮伤害提高15"),("haste","协同装填","炮击间隔缩短，最低1秒"),("multishot","交叉火线","增加一束伴随炮击"),("torpedo","潮汐雷阵","增加雷击并缩短发射间隔"),("magnet","信号牵引","经验拾取半径扩大400米"),("shield","应急装甲","耐久上限增加50并修复80"),("maneuver","跃浪推进","移动速度提高15%"),("blast","破片扩散","炮弹爆炸半径扩大120米"),("repair","纳米修补","每秒恢复1点耐久")];
pub struct Tide{pub seed:u32,pub config:Config,pub tick:u32,p:P,h:f64,hp:f64,maxhp:f64,speed:f64,route:Vec<P>,foes:Vec<Foe>,bolts:Vec<Bolt>,drops:Vec<Drop>,dead:Vec<Value>,events:Vec<Value>,upgrades:std::collections::BTreeMap<String,u32>,choices:Vec<String>,offer:u32,level:u32,xp:u32,kills:u32,elite_kills:u32,boss_dead:bool,boss_spawned:bool,next_gun:u32,next_torp:u32,next_id:u32,rng:u64,pub result:Option<Value>,commands:Vec<Entry>}
impl Tide{
 pub fn new(seed:u32,config:Config)->E<Self>{if !["normal","hard"].contains(&config.difficulty.as_str())||config.intel_profile!=crate::intel::VERSION{return Err("活动难度或公开敌情版本无效".into());}let data=crate::salvage_v3::data()?;if !data.ships.iter().any(|d|d.id==config.character_id&&d.id.starts_with("IBS-U-")){return Err("活动舰娘身份未登记".into());}
  let mut s=Self{seed,config,tick:0,p:P{x:12000.,y:7000.},h:90.,hp:300.,maxhp:300.,speed:35.,route:vec![],foes:vec![],bolts:vec![],drops:vec![],dead:vec![],events:vec![],upgrades:Default::default(),choices:vec![],offer:0,level:1,xp:0,kills:0,elite_kills:0,boss_dead:false,boss_spawned:false,next_gun:0,next_torp:4,next_id:0,rng:seed as u64^0x734d_ab26_77ca,result:None,commands:vec![]};s.event("start","潮汐回响：坚持180秒并击败信号核心。移动拾取经验，强化仅在本局生效。",s.p);s.wave();Ok(s)
 }
 fn event(&mut self,kind:&str,text:&str,p:P){self.events.push(json!({"id":self.events.len()+1,"tick":self.tick,"kind":kind,"text":text,"x":p.x,"y":p.y}));}
 fn id(&mut self)->u32{self.next_id+=1;self.next_id}
 fn rank(&self,id:&str)->u32{*self.upgrades.get(id).unwrap_or(&0)}
 fn xp_required(&self)->u32{8+self.level*4}
 fn wave(&mut self){let n=self.tick/30;let count=if self.config.difficulty=="hard"{16+n*2}else{10+n*2};for i in 0..count{let a=(i as f64*360./count as f64+roll(&mut self.rng,40) as f64)%360.;let p=self.p+P::bearing(a)*(2600.+roll(&mut self.rng,1600) as f64);self.spawn(["scavenger","spitter","cult_ray"][(i as usize+n as usize)%3],p,false,false);}self.event("tide_wave",&format!("第{}潮：海面信号聚集",n+1),self.p);}
 fn spawn(&mut self,kind:&'static str,p:P,elite:bool,boss:bool){let hard=if self.config.difficulty=="hard"{1.35}else{1.};let hp=if boss{560.}else if elite{180.}else{45.}*hard;let id=self.id();self.foes.push(Foe{id,kind,p:P{x:p.x.clamp(600.,23400.),y:p.y.clamp(600.,13400.)},h:0.,hp,max:hp,speed:if boss{65.}else if elite{95.}else{105.},damage:if boss{42.}else if elite{24.}else{12.}*hard,next:self.tick+5,warning:None,elite,boss,hurt:0});}
 fn offer(&mut self){if self.xp<self.xp_required()||!self.choices.is_empty()||self.result.is_some(){return;}self.xp-=self.xp_required();self.level+=1;self.offer+=1;let mut pool:Vec<_>=UPGRADES.iter().filter(|(id,_,_)|self.rank(id)<4).map(|(id,_,_)|id.to_string()).collect();for _ in 0..3{if pool.is_empty(){break;}let i=(roll(&mut self.rng,pool.len() as u32)-1) as usize;self.choices.push(pool.remove(i));}self.event("tide_level","共鸣增强：选择一项本局强化",self.p);}
 pub fn paused(&self)->bool{!self.choices.is_empty()}
 fn finish(&mut self,success:bool){if self.result.is_some(){return;}let tokens=if success{80}else{10}+self.kills.min(120)/3+self.elite_kills*8+if self.boss_dead{30}else{0};self.result=Some(json!({"success":success,"event_tokens":tokens,"score":self.kills*10+self.elite_kills*100+if self.boss_dead{500}else{0},"kills":self.kills,"elite_kills":self.elite_kills,"boss_defeated":self.boss_dead,"duration":self.tick}));self.choices.clear();self.event("end",if success{"潮汐核心已平息，回响结晶已封存"}else{"共鸣中断，舰娘已安全回收"},self.p);}
 pub fn command(&mut self,q:&Value,record:bool)->E<Value>{let op=q["op"].as_str().ok_or("活动操作无效")?;if self.result.is_some(){return Err("活动已经结束".into());}match op{
  "tide_choose"=>{let offer=u32::try_from(q["offer_id"].as_u64().ok_or("缺少强化批次")?).map_err(|_|"强化批次超出范围")?;let id=q["upgrade"].as_str().ok_or("请选择强化")?;if offer!=self.offer||!self.choices.iter().any(|s|s==id){return Err("强化选项已过期或不存在".into());}*self.upgrades.entry(id.into()).or_default()+=1;if id=="shield"{self.maxhp+=50.;self.hp=(self.hp+80.).min(self.maxhp);}self.choices.clear();self.event("tide_upgrade",&format!("获得强化：{}",UPGRADES.iter().find(|u|u.0==id).unwrap().1),self.p);self.offer();},
  "route"=>{let ps:Vec<P>=serde_json::from_value(q["points"].clone()).map_err(|_|"活动航点无效")?;let speed=q["speed"].as_f64().unwrap_or(self.speed);if ps.is_empty()||ps.len()>10||ps.iter().any(|p|!p.x.is_finite()||!p.y.is_finite()||p.x<300.||p.x>23700.||p.y<300.||p.y>13700.)||!speed.is_finite()||!(4. ..=60.).contains(&speed){return Err("航路超出活动海域或速度无效".into());}self.route=ps;self.speed=speed;},
  "speed"=>{let n=q["speed"].as_f64().ok_or("速度无效")?;if !n.is_finite()||!(0. ..=60.).contains(&n){return Err("活动速度须为0–60".into());}self.speed=n;},
  "tide_abandon"=>{self.finish(false);let result=self.result.as_mut().unwrap();result["event_tokens"]=json!(0);result["abandoned"]=json!(true);},_=>return Err("此指令不属于潮汐回响".into())}
 if record{self.commands.push(Entry{tick:self.tick,request:q.clone(),seat:None});}Ok(self.view())}
 pub fn advance(&mut self){if self.result.is_some()||self.paused(){return;}self.tick+=1;let mut distance=self.speed*crate::model::KNOT*10.*(1.+self.rank("maneuver") as f64*0.15);while distance>0.&&!self.route.is_empty(){let target=self.route[0];let d=self.p.dist(target);self.h=(target-self.p).heading();if d<=distance{self.p=target;self.route.remove(0);distance-=d;}else{self.p=self.p+(target-self.p)*(distance/d);distance=0.;}}
 self.hp=(self.hp+self.rank("repair") as f64).min(self.maxhp);
 if self.tick%30==0&&self.tick<180{self.wave();}if [60,120].contains(&self.tick){self.spawn("warden",self.p+P{x:2600.,y:1400.},true,false);self.event("tide_elite","精英信号进入海域",self.p);}if self.tick==150{self.boss_spawned=true;self.spawn("leviathan",self.p+P{x:3000.,y:0.},false,true);self.event("tide_boss","核心实体已显形，击败它并坚持至回收",self.p);}
 for foe in &mut self.foes{if foe.hp<=0.{continue;}let d=foe.p.dist(self.p);foe.h=(self.p-foe.p).heading();if foe.warning.is_none()&&d>900.{foe.p=foe.p+(self.p-foe.p)*(foe.speed/d).min(1.);}
  if let Some((p,due))=foe.warning{if self.tick>=due{if self.p.dist(p)<=if foe.boss{600.}else{300.}{self.hp-=foe.damage;}foe.warning=None;foe.next=self.tick+if foe.boss{5}else{7};}}
  else if self.tick>=foe.next&&d<if foe.boss{3600.}else{2100.}{foe.warning=Some((self.p,self.tick+3));}
 }
 if self.tick>=self.next_gun{if let Some(target)=self.foes.iter().filter(|f|f.hp>0.&&f.p.dist(self.p)<3300.).min_by(|a,b|a.p.dist(self.p).total_cmp(&b.p.dist(self.p))).cloned(){let count=1+self.rank("multishot");for i in 0..count{let id=self.id();self.bolts.push(Bolt{id,p:self.p,h:(target.p-self.p).heading()+(i as f64-(count-1) as f64/2.)*3.,speed:1300.,damage:30.+self.rank("damage") as f64*15.,radius:140.+self.rank("blast") as f64*120.,life:4,kind:"gun"});}self.next_gun=self.tick+(3u32.saturating_sub(self.rank("haste"))).max(1);}}
 if self.tick>=self.next_torp{if let Some(target)=self.foes.iter().filter(|f|f.hp>0.).min_by(|a,b|a.p.dist(self.p).total_cmp(&b.p.dist(self.p))).cloned(){let count=1+self.rank("torpedo");for i in 0..count{let id=self.id();self.bolts.push(Bolt{id,p:self.p,h:(target.p-self.p).heading()+(i as f64-(count-1) as f64/2.)*10.,speed:700.,damage:65.,radius:400.,life:8,kind:"torpedo"});}self.next_torp=self.tick+(8u32.saturating_sub(self.rank("torpedo"))).max(3);}}
 let mut impacts=vec![];for bolt in &mut self.bolts{let end=bolt.p+P::bearing(bolt.h)*bolt.speed;let hit=self.foes.iter().filter(|f|f.hp>0.).filter(|f|crate::adventure::segment_distance(f.p,bolt.p,end)<120.).min_by(|a,b|a.p.dist(bolt.p).total_cmp(&b.p.dist(bolt.p))).map(|f|f.p);bolt.p=end;bolt.life=bolt.life.saturating_sub(1);if let Some(p)=hit{impacts.push((p,bolt.damage,bolt.radius));bolt.life=0;}}
 self.bolts.retain(|b|b.life>0);for(p,damage,radius)in impacts{for f in &mut self.foes{if f.hp>0.&&f.p.dist(p)<=radius{f.hp-=damage;f.hurt=self.tick;}}self.event("tide_hit","炮雷命中",p);}
 let killed:Vec<_>=self.foes.iter().filter(|f|f.hp<=0.).cloned().collect();self.foes.retain(|f|f.hp>0.);for f in killed{self.kills+=1;self.elite_kills+=u32::from(f.elite);self.boss_dead|=f.boss;let id=self.id();self.drops.push(Drop{id,x:f.p.x,y:f.p.y,value:if f.boss{25}else if f.elite{10}else{3}});self.dead.push(json!({"id":format!("T{}",f.id),"source_contact":format!("T{}",f.id),"species":f.kind,"visualType":f.kind,"entityKind":"monster","x":f.p.x,"y":f.p.y,"heading":f.h,"death_tick":self.tick}));}
 let radius=650.+self.rank("magnet") as f64*400.;let picked:u32=self.drops.iter().filter(|d|P{x:d.x,y:d.y}.dist(self.p)<radius).map(|d|d.value).sum();self.drops.retain(|d|P{x:d.x,y:d.y}.dist(self.p)>=radius);self.xp+=picked;self.dead.retain(|d|self.tick-d["death_tick"].as_u64().unwrap() as u32<=5);
 if self.hp<=0.{self.hp=0.;self.finish(false);}else if self.tick>=DURATION{self.finish(self.boss_dead);}else{self.offer();}
 }
 pub fn save(&self)->Saved{Saved{version:VERSION.into(),seed:self.seed,config:self.config.clone(),tick:self.tick,commands:self.commands.clone()}}
 pub fn from_save(s:Saved,tick:Option<u32>)->E<Self>{if s.version!=VERSION||s.tick>DURATION||s.commands.len()>10000||s.commands.iter().any(|c|c.tick>s.tick||c.seat.is_some())||s.commands.windows(2).any(|p|p[0].tick>p[1].tick){return Err("活动存档版本、时钟或命令序列无效".into());}let target=tick.unwrap_or(s.tick).min(s.tick);let mut w=Self::new(s.seed,s.config)?;let mut commands=s.commands.into_iter().peekable();loop{while commands.peek().is_some_and(|c|c.tick==w.tick&&c.tick<=target){let c=commands.next().unwrap();w.command(&c.request,true)?;}if w.tick>=target{break;}if w.paused()||w.result.is_some(){return Err("活动重演在选择或终局后越过时钟".into());}w.advance();}Ok(w)}
 pub fn preview(&self,q:&Value)->Value{let mut fake=json!({"valid":false,"paths":[],"error":"航点无效"});if let Ok(points)=serde_json::from_value::<Vec<P>>(q["points"].clone()){if !points.is_empty()&&points.len()<=10&&points.iter().all(|p|p.x>=300.&&p.x<=23700.&&p.y>=300.&&p.y<=13700.){let mut ps=vec![self.p];ps.extend(points);fake=json!({"valid":true,"paths":[{"ship":1,"points":ps}],"speed":q.get("speed").cloned().unwrap_or(json!(self.speed)),"error":null});}}fake}
 pub fn view(&self)->Value{let mut path=vec![self.p];path.extend(self.route.iter().copied());let contacts:Vec<_>=self.foes.iter().map(|f|json!({"id":format!("T{}",f.id),"x":f.p.x,"y":f.p.y,"heading":f.h,"speed":f.speed/(crate::model::KNOT*10.),"kind":"monster","name":if f.boss{"回响核心"}else if f.elite{"精英礁脊"}else{"潮汐异种"},"entityKind":"monster","species":f.kind,"visualType":f.kind,"boss":f.boss,"elite":f.elite,"health":f.hp,"max_health":f.max,"health_fraction":f.hp/f.max,"hurt_tick":f.hurt,"attack":{"kind":"pulse","state":if f.warning.is_some(){"windup"}else if self.tick<f.next{"recover"}else{"approach"},"label":"回响冲击","counter":"离开圆形锁定点","seconds":f.warning.map_or(f.next.saturating_sub(self.tick),|(_,t)|t.saturating_sub(self.tick)),"range":if f.boss{3600}else{2100},"radius":if f.boss{600}else{300},"shape":"circle"},"intelligence":{"speed_max":f.speed/(crate::model::KNOT*10.),"attack_damage":f.damage,"attack_range":if f.boss{3600}else{2100},"attack_cooldown":if f.boss{8}else{10},"armor":0,"weaknesses":"保持移动、集中火力并拾取经验"}})).collect();
 let warnings:Vec<_>=self.foes.iter().filter_map(|f|f.warning.map(|(p,due)|json!({"id":f.id,"source_contact":format!("T{}",f.id),"kind":"pulse","name":"回响冲击","counter":"离开圆形锁定点","shape":"circle","x":p.x,"y":p.y,"radius":if f.boss{600}else{300},"start_tick":due-3,"impact_tick":due,"exempt_ship_id":null}))).collect();
 let choices:Vec<_>=self.choices.iter().map(|id|{let u=UPGRADES.iter().find(|u|u.0==id).unwrap();json!({"id":u.0,"name":u.1,"description":u.2,"icon":u.0,"rank":self.rank(id)+1})}).collect();let result=self.result.as_ref().map(|r|json!({"winner":if r["success"]==true{"allies"}else{"axis"},"primary":r["success"],"allies":self.kills,"axis":0}));
 json!({"version":VERSION,"scenario":"潮汐回响","tick":self.tick,"limit":DURATION,"width":24000,"height":14000,"side":"allies","intel_profile":crate::intel::VERSION,"islands":[],"ships":[{"id":1,"name":"共鸣舰娘","characterId":self.config.character_id,"kind":"dd","fleet":1,"x":self.p.x,"y":self.p.y,"heading":self.h,"speed":if self.route.is_empty(){0.}else{self.speed},"hp":self.hp,"maxHp":self.maxhp,"hullLengthM":100,"gunRange":3300,"torpedoRange":5600,"gun":true,"torpedo":true,"ammo":999,"systems":{"guns":[],"tubes":[],"maxSpeed":60}}],"fleets":[{"id":1,"leader":1,"members":[1],"name":"回响编队","mode":"follow","speed":self.speed,"actual":if self.route.is_empty(){0.}else{self.speed},"maxSpeed":60,"points":self.route,"paths":[{"ship":1,"points":path}]}],"contacts":contacts,"shells":self.bolts.iter().filter(|b|b.kind=="gun").map(|b|json!({"id":b.id,"x":b.p.x,"y":b.p.y,"heading":b.h,"side":"allies"})).collect::<Vec<_>>(),"torpedoes":self.bolts.iter().filter(|b|b.kind=="torpedo").map(|b|json!({"id":b.id,"x":b.p.x,"y":b.p.y,"heading":b.h,"side":"allies","own":true})).collect::<Vec<_>>(),"events":self.events.iter().rev().take(40).collect::<Vec<_>>(),"result":result,"salvage":{"content":VERSION,"generatorVersion":"archipelago-tide-1","terrainTheme":"atoll","landmarks":[],"telegraphs":warnings,"defeated_entities":self.dead,"adventure":{"version":VERSION,"movement_multiplier":10}},"tide":{"version":VERSION,"duration":DURATION,"wave":(self.tick/30+1).min(6),"kills":self.kills,"elite_kills":self.elite_kills,"boss_defeated":self.boss_dead,"boss_spawned":self.boss_spawned,"level":self.level,"xp":self.xp,"xp_required":self.xp_required(),"drops":self.drops,"upgrades":self.upgrades,"choices":choices,"offer_id":self.offer,"paused":self.paused(),"outcome":self.result}})
 }
}
#[cfg(test)]mod tests{use super::*;
 fn new()->Tide{Tide::new(42,Config{character_id:"IBS-U-USN-FLETCHER".into(),difficulty:"normal".into(),intel_profile:crate::intel::VERSION.into()}).unwrap()}
 #[test]fn stationary_player_really_loses_and_rewards_are_bounded(){let mut w=new();for _ in 0..180{w.advance();if w.result.is_some(){break;}}assert_eq!(w.result.as_ref().unwrap()["success"],false);assert!(w.tick<180);assert!(w.kills>0);assert!(w.result.as_ref().unwrap()["event_tokens"].as_u64().unwrap()<80);assert_eq!(Tide::from_save(w.save(),None).unwrap().view(),w.view());}
 #[test]fn upgrade_is_a_paused_versioned_three_way_choice_and_cannot_repeat(){let mut w=new();w.xp=20;w.offer();assert_eq!(w.choices.len(),3);let tick=w.tick;w.advance();assert_eq!(w.tick,tick);let id=w.choices[0].clone();let q=json!({"op":"tide_choose","offer_id":w.offer,"upgrade":id});w.command(&q,true).unwrap();assert_eq!(w.rank(&id),1);assert!(w.command(&q,true).is_err());}
 #[test]fn wrong_activity_or_upgrade_values_are_rejected_atomically(){let mut w=new();let before=w.view();assert!(w.command(&json!({"op":"tide_choose","offer_id":0,"upgrade":"damage"}),true).is_err());assert_eq!(before,w.view());assert!(Tide::new(42,Config{difficulty:"unknown".into(),..w.config.clone()}).is_err());assert!(w.command(&json!({"op":"route","points":[{"x":-1,"y":7000}]}),true).is_err());}
 #[test]fn quitting_never_awards_activity_currency(){let mut w=new();w.command(&json!({"op":"tide_abandon"}),true).unwrap();assert_eq!(w.result.as_ref().unwrap()["event_tokens"],0);assert_eq!(w.result.as_ref().unwrap()["abandoned"],true);assert_eq!(Tide::from_save(w.save(),None).unwrap().view(),w.view());}
}
